import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Store1 from './components/Store1';
import Store2 from './components/Store2';
import StockOperations from './components/Store3/StockOperations';
import SalesOperations from './components/Store3/SalesOperations';
import ReturnOperations from './components/Store3/ReturnOperations';
import './App.css';

function App() {
  return (
    <Router>
      <div className="flex">
        <Sidebar />
        <div className="flex-1 ml-64">
          <Routes>
            <Route path="/" element={<Dashboard />} />
            <Route path="/store1" element={<Store1 />} />
            <Route path="/store2" element={<Store2 />} />
            <Route path="/store3/stock" element={<StockOperations />} />
            <Route path="/store3/sales" element={<SalesOperations />} />
            <Route path="/store3/returns" element={<ReturnOperations />} />
          </Routes>
        </div>
      </div>
    </Router>
  );
}

export default App;
